#include <stdio.h>

int add_bonus(int points) {
    int bonus = 50;
    return points + bonus;
}

int score_hit(int base) {
    int doubled = base * 2;
    return add_bonus(doubled);
}

int main(void) {
    int score = 0;
    score = score_hit(100);
    printf("score = %d\n", score);
    return 0;
}

